handler(POST /payments, Idempotency-Key k):
  try {
    tx {
      insertKey(k)                      // UNIQUE(key)
      insertPayment(...)
      storeResponse(k, 201 Created)
    }
  } catch (UniqueViolation) {
    email.send(customer, "payment received")
    return storedResponse(k)
  }
  email.send(customer, "payment received")
